-- Migration to add unique constraint on name and seed rich exercises with instructions & GIFs

-- 1. Add unique constraint on name (if it doesn't already exist)
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'exercises_name_key') then
    alter table public.exercises add constraint exercises_name_key unique (name);
  end if;
end $$;

-- 2. Seed exercises
on conflict (name) do update 
set muscle_group = excluded.muscle_group,
    instructions = excluded.instructions,
    gif_url = excluded.gif_url;
